-- Esquema EQUIVALENTE en SQLite, solo para las pruebas automaticas sin MySQL (pruebas/run_tests.sh)
CREATE TABLE j4rol (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT NOT NULL);
INSERT INTO j4rol VALUES (1,'admin','Admin'),(2,'user','User generic');
CREATE TABLE j4user (id INTEGER PRIMARY KEY AUTOINCREMENT, user TEXT NOT NULL UNIQUE, password TEXT NOT NULL, keyAPI TEXT NOT NULL, roles INTEGER NOT NULL, dateDelete TIMESTAMP NULL);
INSERT INTO j4user VALUES (1,'admin','$2y$10$rCdykaN0YQL/H4VJW0RKae69B2QekbrO3Iuj8OxFy/V1syHOmpfmO','750e8b43e5ed564462c90ef0d382db26',1,NULL);
CREATE TABLE documenttype (id INTEGER PRIMARY KEY AUTOINCREMENT, longName TEXT NOT NULL, shortName TEXT NOT NULL, dateDelete TIMESTAMP NULL);
INSERT INTO documenttype(longName,shortName) VALUES ('Cédula de ciudadanía','CC'),('NIT','NIT');
CREATE TABLE person (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, lastName TEXT NOT NULL, phone TEXT NOT NULL, dateDelete TIMESTAMP NULL, documentTypeId INTEGER NULL REFERENCES documenttype(id));
CREATE TABLE customer (id INTEGER PRIMARY KEY AUTOINCREMENT, documentTypeId INTEGER NULL REFERENCES documenttype(id), document TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL, address TEXT NOT NULL, dateDelete TIMESTAMP NULL);
CREATE TABLE vehicle (id INTEGER PRIMARY KEY AUTOINCREMENT, plate TEXT NOT NULL, model INTEGER NOT NULL, color TEXT NOT NULL, customerId INTEGER NOT NULL REFERENCES customer(id), entryDate TEXT NOT NULL, entryTime TEXT NOT NULL, dateDelete TIMESTAMP NULL);
CREATE TABLE employee (id INTEGER PRIMARY KEY AUTOINCREMENT, document TEXT NOT NULL, firstName TEXT NOT NULL, lastName TEXT NOT NULL, position TEXT NOT NULL, dateDelete TIMESTAMP NULL);
CREATE TABLE invoice (id INTEGER PRIMARY KEY AUTOINCREMENT, customerId INTEGER NULL REFERENCES customer(id), customerName TEXT NOT NULL, customerDocument TEXT NOT NULL, issueDate TEXT NOT NULL, total REAL NOT NULL, status TEXT NOT NULL, clarisaNumber TEXT NULL, items TEXT NULL, requestJson TEXT NULL, responseJson TEXT NULL, createdBy TEXT NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, dateDelete TIMESTAMP NULL);
